from mk import *
from lib import fbd
STRICT["on"] = True
from lib import mini

def fig():
    g = Fig(560, 330, "מסילה חלקה ABCD: קטע אופקי AB, עלייה BC וקטע אופקי גבוה CD. קרונית 1 במסה 2 קילוגרם נעה ימינה לעבר קרונית 2 שבמנוחה. גרף הכוח של קרונית 1 על קרונית 2: משולש עד 10 בחזקת 4 ניוטון ב-0.5 אלפיות שנייה, וחזרה לאפס באלפית שנייה. ושלושה גרפי מהירות אפשריים")
    g.path("M 30,120 L 330,120 Q 360,120 400,70 Q 420,46 450,46 L 530,46", width=2.5)
    for x, lab in ((120, "1"), (250, "2")):
        g.rect(x - 32, 94, 64, 22, fill="none", rx=5); g.text(x, 110, lab)
        for w in (x - 18, x + 18): g.circle(w, 118, 4, fill="none", stroke="var(--d-line)")
    g.arrow(155, 88, 190, 88, "v₁", lx=172, ly=80)
    for x, y, t in ((30, 136, "A"), (330, 136, "B"), (440, 36, "C"), (528, 36, "D")): g.text(x, y, t)
    X, Y = g.graph(70, 270, 160, 100, "t (ms)", "F (N)", xticks=[(1, "1")], yticks=[(1, "10⁴")], xmax=1.3, ymax=1.2, grid=False)
    g.plot(X, Y, [(0, 0), (0.5, 1), (1, 0)]); g.line(X(0), Y(1), X(0.5), Y(1), stroke="var(--d-dim)", width=1, dash="4 3")
    for i, (lab, pts) in enumerate([("3", [(0, 0.85), (0.3, 0.85), (0.3, 0.6), (0.65, 0.6), (0.65, 0.35), (0.9, 0.35)]), ("2", [(0, 0.35), (0.5, 0.35), (0.65, 0.65), (0.95, 0.65)]), ("1", [(0, 0.65), (0.5, 0.65), (0.65, 0.35), (0.95, 0.35)])]):
        mini(g, 290 + i * 90, 270, 70, 90, pts=pts, label=lab, yl="v")
    return g

def third_law_fig():
    g = Fig(420, 300, "גרף הכוח כפונקציה של הזמן: הכוח של קרונית 1 על קרונית 2 הוא משולש מעל הציר עד עשר בחזקת ארבע ניוטון, והכוח של קרונית 2 על קרונית 1 הוא אותו משולש מתחת לציר")
    X, Y = g.graph(70, 150, 300, 110, "t (ms)", "F (N)", xticks=[(0.5, "0.5"), (1, "1")], yticks=[(1, "10⁴"), (-1, "−10⁴")], xmax=1.3, ymin=-1.2, ymax=1.2, grid=False)
    g.plot(X, Y, [(0, 0), (0.5, 1), (1, 0)])
    g.plot(X, Y, [(0, 0), (0.5, -1), (1, 0)], stroke="var(--d-ask)", dash="6 4")
    g.text(X(0.62), Y(0.95), "F₁₂", anchor="start"); g.text(X(0.62), Y(-0.95) + 10, "F₂₁", anchor="start", color="var(--d-ask)")
    return g

E(id="bagrut-2012-q4", year=2012, label="2012 שאלה 4", topic="momentum", sub="mom-collisions", diff=3, fig=fig,
  stem=r"תרשים א מראה מסילה חלקה $ABCD$. קרונית 1, שמסתה $m_1 = 2\,\text{kg}$, נוסעת ימינה על הקטע האופקי $AB$ במהירות $v_1$. היא מתנגשת חזיתית, התנגשות אלסטית, בקרונית 2 שעומדת על הקטע $AB$. תרשים ב מראה את הכוח $F$ שקרונית 1 הפעילה על קרונית 2 בזמן ההתנגשות, כפונקציה של הזמן.",
  parts=[
    P("א", r"איזה גודל פיזיקלי מייצג השטח שבין העקומה בתרשים ב לציר הזמן?", choice(["המתקף שקרונית 1 הפעילה על קרונית 2", "העבודה שקרונית 1 עשתה על קרונית 2", "התאוצה של קרונית 2", "האנרגיה הקינטית של קרונית 2"], 0), ["graph", "principle"], [
        S(r"שטח מתחת לגרף כוח-זמן", r"בכל פרק זמן קצר השטח הוא כוח כפול זמן, וזה המתקף. השטח כולו הוא המתקף בכל ההתנגשות", r"J = F\,\Delta t", eq=r"\vec J_{\text{tot}} = \Delta\vec p"),
    ], r"את המתקף שקרונית 1 הפעילה על קרונית 2", key=r"המתקף שקרונית 1 הפעילה על קרונית 2"),
    P("ב", r"אחרי ההתנגשות קרונית 2 נוסעת ימינה במהירות $u_2 = 1.25\,\text{m/s}$. מה המסה $m_2$ של קרונית 2?", num(4, "kg"), ["graph", "principle", "units"], [
        S(r"המתקף מהגרף", r"השטח של משולש: חצי בסיס כפול גובה. ממירים אלפיות שנייה לשניות", r"J = \tfrac{1}{2} \cdot 10^{-3} \cdot 10^{4} = 5\,\text{N}\cdot\text{s}"),
        S(r"שינוי התנע של קרונית 2", r"המתקף שווה לשינוי התנע. הקרונית התחילה ממנוחה", r"5 = m_2 \cdot 1.25 - 0 \;\Rightarrow\; m_2 = 4\,\text{kg}", eq=r"\vec J_{\text{tot}} = \Delta\vec p"),
    ], r"$4\,\text{kg}$", key=r"m2=4 kg"),
    P("ג", r"כתבו שתי משוואות שמהן אפשר לחשב את המהירות של קרונית 1 לפני ההתנגשות, והציבו בהן את הערכים. אין צורך לפתור.", OPEN, ["principle"], [
        X(r"ימינה הוא הכיוון החיובי. מסמנים את המהירות של קרונית 1 אחרי ההתנגשות בסימן משלה."),
        S(r"שימור תנע", r"קרונית 2 עמדה לפני ההתנגשות", r"2\,v_1 + 0 = 2\,u_1 + 4 \cdot 1.25", eq=r"m_A\vec v_A + m_B\vec v_B = m_A\vec u_A + m_B\vec u_B"),
        S(r"התנגשות אלסטית", r"מהירות ההתקרבות שווה למהירות ההתרחקות. אפשר גם לכתוב שימור אנרגיה קינטית", r"v_1 - 0 = -(u_1 - 1.25)", eq=r"v_A - v_B = -(u_A - u_B)"),
    ], r"$2v_1 = 2u_1 + 5$ וגם $v_1 = -u_1 + 1.25$", key=r"2v1=2u1+5 ; v1=−u1+1.25"),
    P("ד", r"העתיקו את תרשים ב, והוסיפו לו עקומה של הכוח שקרונית 2 הפעילה על קרונית 1 בזמן ההתנגשות.", OPEN, ["graph", "principle"], [
        S(r"החוק השלישי של ניוטון", r"בכל רגע הכוח של קרונית 2 על קרונית 1 שווה בגודלו לכוח של קרונית 1 על קרונית 2, ובכיוון הפוך", r"\vec F_{2,1}(t) = -\vec F_{1,2}(t)", eq=r"\vec F_{1,2} = -\vec F_{2,1}"),
        D(r"הגרף עם שתי העקומות", third_law_fig),
    ], r"אותו משולש, מתחת לציר הזמן, עד מינוס עשר בחזקת ארבע ניוטון"),
    P("ה", r"בשלב מסוים קרונית 2 עולה בקטע $BC$ וממשיכה לנסוע בקטע $CD$. איזה מהגרפים (1) עד (3) מתאר נכון את גודל המהירות של קרונית 2 כפונקציה של הזמן, מסוף ההתנגשות עד שהיא מגיעה ל-$D$? נמקו.", choice(["1", "2", "3"], 0), ["graph", "principle"], [
        S(r"בקטע הראשון", r"הקטע אופקי וחלק, ולכן אין כוח בכיוון התנועה והמהירות קבועה", r"v = 1.25\,\text{m/s}"),
        S(r"בעלייה", r"רכיב הכובד לאורך המסילה פועל נגד התנועה, ולכן המהירות קטנה בהדרגה, לא בבת אחת", r"a < 0"),
        S(r"בקטע העליון", r"שוב קטע אופקי וחלק, ולכן המהירות קבועה, אבל נמוכה יותר כי הקרונית גבוהה יותר", r"\tfrac{1}{2}mv_{CD}^2 = \tfrac{1}{2}m \cdot 1.25^2 - mgh", eq=r"E_k = \tfrac{1}{2}mv^2,\quad U_G = mgh"),
    ], r"גרף 1", key=r"גרף 1"),
  ],
  concepts=["מתקף", "שטח מתחת לגרף כוח-זמן", "התנגשות אלסטית", "החוק השלישי של ניוטון"],
  summary=r"התנגשות אלסטית של קרוניות: מתקף מגרף משולש, המסה של הקרונית השנייה, והמהירות שלה בעלייה.",
  review="הנחה שלי.\nבסעיף א התלמיד בוחר מתוך ארבע אפשרויות. בסעיף ד יש בפתרון ציור של שתי העקומות.\nמה לבדוק: רק לאשר.")
